typedef struct Node {
    int data;
    struct Node* next;
} Node_t;

typedef struct Tree_Node {
    void* payload;
    struct Tree_Node* left;
    struct Tree_Node* right;
} Tree_Node_t;

// Forward declaration needed for mutual dependency
struct Data_B;

typedef struct Data_A {
    int identifier;
    struct Data_B* ref_b; // Dependent pointer
} Data_A_t;

struct Data_B {
    char name[10];
    Data_A_t* ref_a;
};

typedef enum { LEAF, BRANCH } Node_Type;

typedef struct Complex_Node {
    Node_Type type;
    union {
        void* leaf_data;
        struct Complex_Node* children[2];
    } payload;
} Complex_Node_t;
